/* sprite data for E1M1 from freedoom1.wad */

SET NOCOUNT ON;

DELETE FROM dbo.sprite_column;
DELETE FROM dbo.sprite_frame;
DELETE FROM dbo.mobj_type;













































































































SELECT frames = (SELECT COUNT(*) FROM dbo.sprite_frame),
       columns_ = (SELECT COUNT(*) FROM dbo.sprite_column),
       types = (SELECT COUNT(*) FROM dbo.mobj_type);
